  import express, { type NextFunction, type Request, type Response } from "express";
  import { TaskManagementService, type CreateTaskInput } from "../application/task-management-service";
  import { DomainError, type TaskStatus } from "../domain/entities";

  type Body = Record<string, unknown>;

  const body = (request: Request): Body => request.body as Body;
  const stringField = (value: unknown): string => value as string;
  const optionalStringField = (value: unknown): string | undefined =>
    value === undefined ? undefined : (value as string);

  export function createApp(service = new TaskManagementService()): express.Express {
    const app = express();
    app.use(express.json());

    app.post("/users", (request, response, next) => {
      try {
        response.status(201).json(service.createUser(stringField(body(request).name)));
      } catch (error) { next(error); }
    });

    app.post("/projects", (request, response, next) => {
      try {
        response.status(201).json(service.createProject(stringField(body(request).name)));
      } catch (error) { next(error); }
    });

    app.post("/projects/:projectId/tasks", (request, response, next) => {
      try {
        const input: CreateTaskInput = {
          title: stringField(body(request).title),
          description: stringField(body(request).description),
          dueDate: optionalStringField(body(request).dueDate),
          status: optionalStringField(body(request).status) as TaskStatus | undefined,
          assigneeId: optionalStringField(body(request).assigneeId),
        };
        response.status(201).json(service.createTask(request.params.projectId, input));
      } catch (error) { next(error); }
    });

    app.get("/projects/:projectId/tasks", (request, response, next) => {
      try {
        const status = typeof request.query.status === "string" ? request.query.status as TaskStatus : undefined;
        const assigneeId = typeof request.query.assigneeId === "string" ? request.query.assigneeId : undefined;
        response.json(service.listProjectTasks(request.params.projectId, { status, assigneeId }));
      } catch (error) { next(error); }
    });

    app.patch("/tasks/:taskId/assignee", (request, response, next) => {
      try {
        response.json(service.assignTask(request.params.taskId, stringField(body(request).assigneeId)));
      } catch (error) { next(error); }
    });

    app.patch("/tasks/:taskId/done", (request, response, next) => {
      try {
        response.json(service.markTaskDone(request.params.taskId));
      } catch (error) { next(error); }
    });

    app.use((_request: Request, response: Response) => response.status(404).json({ error: "Not found" }));
    app.use((error: unknown, _request: Request, response: Response, _next: NextFunction) => {
      if (error instanceof DomainError) {
        response.status(error.statusCode).json({ error: error.message });
        return;
      }
      response.status(500).json({ error: "Internal server error" });
    });
    return app;
  }

